import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './EditarPerfil.css';

import menuItems from '../../data/menuItems';
import Base_Main from "../../bases/Base_Main";
import Base_AsideIZ from "../../bases/Base_AsideIZ";
import Base_AsideDE from "../../bases/Base_AsideDE";

import {
    getPublicacionesPorPerfil,
    getComentariosPorPublicacion,
    estaAutenticado,
    getUsuarioActual
} from "../../Api";

// Helper para obtener usuario de forma segura
const getUsuarioLogeado = () => {
    try {
        const data = localStorage.getItem("usuarioLogeado");
        return data ? JSON.parse(data) : null;
    } catch (error) {
        console.error("Error al leer usuario:", error);
        return null;
    }
};

const EditarPerfil = () => {
    const navigate = useNavigate();
    const [usuarioLogeado, setUsuarioLogeado] = useState(null);
    const [activeTab, setActiveTab] = useState('publicaciones');
    const [posts, setPosts] = useState([]);
    const [comentarios, setComentarios] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selectedTablon, setSelectedTablon] = useState('');
    const [selectedDate, setSelectedDate] = useState('');

    // Verificar autenticación al montar
    useEffect(() => {
        const usuario = getUsuarioActual();

        if (!usuario) {
            console.log("No hay usuario logeado, redirigiendo a /cuenta");
            navigate("/cuenta");
            return;
        }

        setUsuarioLogeado(usuario);
    }, [navigate]);

    // Cargar publicaciones cuando el usuario esté disponible
    useEffect(() => {
        if (!usuarioLogeado || !usuarioLogeado.perfil || !usuarioLogeado.perfil.id) {
            return;
        }

        cargarPublicacionesYComentarios();
    }, [usuarioLogeado?.perfil?.id]);

    // Cargar publicaciones y comentarios del usuario
    const cargarPublicacionesYComentarios = async () => {
        if (!usuarioLogeado || !usuarioLogeado.perfil || !usuarioLogeado.perfil.id) {
            console.error("No hay usuario válido");
            return;
        }

        try {
            setLoading(true);
            setError(null);

            console.log("Cargando publicaciones del usuario ID:", usuarioLogeado.perfil.id);
            const data = await getPublicacionesPorPerfil(usuarioLogeado.perfil.id);

            const publicaciones = Array.isArray(data)
                ? data
                : Array.isArray(data.results)
                    ? data.results
                    : [];

            console.log(`${publicaciones.length} publicaciones cargadas`);

            // Formatear publicaciones
            const publicacionesFormateadas = publicaciones.map(pub => ({
                id: pub.id,
                perfilId: pub.perfil,
                author: pub.perfil_info?.nom_usuario || usuarioLogeado.perfil.nom_usuario,
                avatar: pub.perfil_info?.foto_perfil || usuarioLogeado.perfil.foto_perfil || "/default-avatar.png",
                date: new Date(pub.fecha_pub).toLocaleString("es-MX", {
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit",
                    hour: "2-digit",
                    minute: "2-digit",
                }),
                content: pub.texto,
                image: pub.fotos && pub.fotos.length > 0 ? pub.fotos[0].ruta_foto : null,
                kudos: pub.like_pub,
                fecha_pub: pub.fecha_pub,
            }));

            setPosts(publicacionesFormateadas);

            // Cargar todos los comentarios de todas las publicaciones
            await cargarTodosLosComentarios(publicacionesFormateadas);
        } catch (err) {
            console.error("Error al cargar publicaciones:", err);
            setError("No se pudieron cargar las publicaciones");
        } finally {
            setLoading(false);
        }
    };

    // Cargar comentarios de todas las publicaciones
    const cargarTodosLosComentarios = async (publicaciones) => {
        try {
            const todosLosComentarios = [];

            for (const post of publicaciones) {
                const comentariosPost = await getComentariosPorPublicacion(post.id);

                const comentariosFormateados = comentariosPost.map(com => ({
                    id: com.id,
                    publicacionId: post.id,
                    author: com.perfil_info?.nom_usuario || "Usuario",
                    avatar: com.perfil_info?.foto_perfil || "/default-avatar.png",
                    text: com.texto,
                    kudos: com.like_com,
                    date: new Date(com.fecha_com).toLocaleString("es-MX", {
                        year: "numeric",
                        month: "2-digit",
                        day: "2-digit",
                        hour: "2-digit",
                        minute: "2-digit",
                    }),
                    fecha_com: com.fecha_com,
                }));

                todosLosComentarios.push(...comentariosFormateados);
            }

            setComentarios(todosLosComentarios);
            console.log(`${todosLosComentarios.length} comentarios cargados`);
        } catch (err) {
            console.error("Error al cargar comentarios:", err);
        }
    };

    // Filtrar contenido según tab activo
    const getContenidoFiltrado = () => {
        let contenido = [];

        if (activeTab === 'publicaciones') {
            contenido = posts;
        } else if (activeTab === 'comentarios') {
            contenido = comentarios;
        } else if (activeTab === 'todo') {
            // Combinar posts y comentarios
            const postsConTipo = posts.map(p => ({ ...p, tipo: 'publicacion' }));
            const comentariosConTipo = comentarios.map(c => ({ ...c, tipo: 'comentario' }));
            contenido = [...postsConTipo, ...comentariosConTipo].sort((a, b) => {
                const fechaA = new Date(a.fecha_pub || a.fecha_com);
                const fechaB = new Date(b.fecha_pub || b.fecha_com);
                return fechaB - fechaA; // Más reciente primero
            });
        }

        // Aplicar filtros
        if (selectedDate) {
            contenido = contenido.filter(item => {
                const itemDate = new Date(item.fecha_pub || item.fecha_com);
                const filterDate = new Date(selectedDate);
                return itemDate.toDateString() === filterDate.toDateString();
            });
        }

        return contenido;
    };

    const contenidoFiltrado = getContenidoFiltrado();

    // Si no hay usuario, mostrar loading
    if (!usuarioLogeado) {
        return (
            <div className='editar-grid'>
                <Base_AsideIZ usuario={null} />
                <Base_Main tituloPagina="Editar Perfil">
                    <div className="edit-main-content">
                        <p>Cargando...</p>
                    </div>
                </Base_Main>
                <Base_AsideDE />
            </div>
        );
    }

    return (
        <div className='editar-grid'>
            {/* ASIDE IZQUIERDO - usando la base */}
            <Base_AsideIZ usuario={usuarioLogeado} />

            {/* MAIN - usando la base */}
            <Base_Main tituloPagina="Editar Perfil">
                <div className="edit-main-content">
                    {/* === PERFIL === */}
                    <div className="edit-cont-perfil">
                        <div className="edit-ima-perf">
                            <img 
                                src={usuarioLogeado.perfil?.foto_perfil || "/default-avatar.png"} 
                                alt="foto de perfil" 
                            />
                            <button className="edit">
                                <i className="bi bi-pencil-square"></i>
                            </button>
                            <button className="delet">
                                <i className="bi bi-trash3"></i>
                            </button>
                        </div>

                        <div className="edit-descrip-perf">
                            <div className="edit-nom">
                                <h2>{usuarioLogeado.perfil?.nom_usuario || usuarioLogeado.usuario?.nombre}</h2>
                                <button className="edit">
                                    <i className="bi bi-pencil-square"></i>
                                </button>
                            </div>
                            <div className="edit-desc">
                                <p>{usuarioLogeado.perfil?.biografia || "Sin descripción"}</p>
                                <div className="edit-desc-buttons">
                                    <button className="edit">
                                        <i className="bi bi-pencil-square"></i>
                                    </button>
                                    <button className="delet">
                                        <i className="bi bi-trash3"></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <hr />

                    {/* === CONFIGURACIÓN DE PÁGINA === */}
                    <div className="edit-page">
                        <h5>Página</h5>
                        <div className="edit-color-page">
                            <label>Color de página: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-color-fondo">
                            <label>Color de fondo: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-image-fondo">
                            <label>Imagen de fondo: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-tipo-font">
                            <label>Tipo de letra: </label>
                            <div>
                                <button>Editar</button>
                                <button>Borrar</button>
                            </div>
                        </div>
                        <div className="edit-tam">
                            <label>Tamaño de letra: </label>
                            <input
                                type="range"
                                id="tam-font"
                                name="tam-font"
                                min="0"
                                max="40"
                                defaultValue="13"
                            />
                        </div>
                    </div>

                    <hr />

                    {/* === POSTS / COMENTARIOS === */}
                    <div className="edit-com-post">
                        <h5>Post / Comentario</h5>

                        {/* Select dinámico */}
                        <div className="edit-tap">
                            <select 
                                name="opcion-tab" 
                                id="opcion-tab" 
                                value={selectedTablon}
                                onChange={(e) => setSelectedTablon(e.target.value)}
                            >
                                <option value="">
                                    Todos los tablones
                                </option>
                                {menuItems.slice(1).map((item) => (
                                    <option key={item.id} value={item.id}>
                                        {item.label}
                                    </option>
                                ))}
                            </select>
                            <input
                                type="date"
                                id="fecha"
                                name="fecha"
                                min="2025-01-01"
                                max="2030-12-31"
                                value={selectedDate}
                                onChange={(e) => setSelectedDate(e.target.value)}
                            />
                        </div>

                        <div className="edit-pest">
                            <button 
                                data-tab="comentarios" 
                                className={activeTab === 'comentarios' ? 'active' : ''}
                                onClick={() => setActiveTab('comentarios')}
                            >
                                Comentarios ({comentarios.length})
                            </button>
                            <button 
                                data-tab="publicaciones"
                                className={activeTab === 'publicaciones' ? 'active' : ''}
                                onClick={() => setActiveTab('publicaciones')}
                            >
                                Publicaciones ({posts.length})
                            </button>
                            <button 
                                data-tab="todo"
                                className={activeTab === 'todo' ? 'active' : ''}
                                onClick={() => setActiveTab('todo')}
                            >
                                Todo ({posts.length + comentarios.length})
                            </button>
                        </div>

                        {/* Render dinámico de posts/comentarios */}
                        <div className="content-edit">
                            <div className="tab-content activate">
                                {loading ? (
                                    <div className="edit-sin-datos">
                                        <p>Cargando...</p>
                                    </div>
                                ) : error ? (
                                    <div className="edit-sin-datos" style={{ color: 'red' }}>
                                        <p>{error}</p>
                                    </div>
                                ) : contenidoFiltrado.length === 0 ? (
                                    <div className="edit-sin-datos">
                                        <p>No hay {activeTab === 'comentarios' ? 'comentarios' : activeTab === 'publicaciones' ? 'publicaciones' : 'contenido'} para mostrar</p>
                                    </div>
                                ) : (
                                    <div className="all-post">
                                        {contenidoFiltrado.map((item) => (
                                            <div key={`${item.tipo || 'post'}-${item.id}`} className="blog-post">
                                                <div className="post-perf">
                                                    <div className="info-main">
                                                        <img
                                                            className="ima-inf"
                                                            src={item.avatar}
                                                            alt={`avatar de ${item.author}`}
                                                        />
                                                        <h6 className="nombre">{item.author}</h6>
                                                        <h6 className="public">
                                                            {item.tipo === 'comentario' ? 'Comentó' : 'Publicó'}
                                                        </h6>
                                                        <h6 className="fecha">{item.date}</h6>
                                                    </div>
                                                    <div className="post">
                                                        <p>{item.content || item.text}</p>
                                                    </div>
                                                    {item.image && (
                                                        <div className="post-ima">
                                                            <img
                                                                className="ima-pub"
                                                                src={item.image}
                                                                alt="imagen del post"
                                                            />
                                                        </div>
                                                    )}
                                                    <div className="opciones-botton">
                                                        <a className="check" href="#">
                                                            [check]
                                                        </a>
                                                        <button className="kudos">
                                                            <i className="bi bi-bug-fill"></i>
                                                            <span style={{ marginLeft: '5px', fontSize: '12px' }}>
                                                                {item.kudos || 0}
                                                            </span>
                                                        </button>
                                                        <div className="edit-buttons">
                                                            <button className="edit">
                                                                <i className="bi bi-pencil-square"></i>
                                                            </button>
                                                            <button className="delet">
                                                                <i className="bi bi-trash3"></i>
                                                            </button>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </Base_Main>

            {/* ASIDE DERECHO - usando la base */}
            <Base_AsideDE />
        </div>
    );
};

export default EditarPerfil;
